import json,html
from pathlib import Path
r=Path(__file__).resolve().parent.parent;t=json.loads((r/'src/texts.json').read_text())
for lang in ('zh','en'):
 d=t[lang]; e=lambda k:html.escape(d[k]);prefix='' if lang=='zh' else '../'
 def text(k,tag='span',attrs=''):return f'<{tag} data-t="{k}" {attrs}>{e(k)}</{tag}>'
 controls=''
 for key in ('width','height'):
  controls+=f'<label for="{key}Raw" data-t="{key}">{e(key)}</label><input id="{key}Raw" type="text" inputmode="numeric" autocomplete="off" spellcheck="false" aria-describedby="dimensionHint error" value="'+('240' if key=='width' else '160')+'">'
 options=lambda keys:''.join(f'<option value="{k}" data-t="{k}">{e(k)}</option>' for k in keys)
 body=f'''<!doctype html><html lang="{'zh-Hant' if lang=='zh' else 'en'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{e('title')} · GlossQuote</title><meta name="description" content="{e('subtitle')}"><link rel="stylesheet" href="{prefix}assets/styles.css"><script type="module" src="{prefix}assets/app.mjs"></script></head><body><header><a id="home" href="https://glossquote.com/{'en/' if lang=='en' else ''}index.html">{e('home')}</a><a id="route" href="{'../index.html' if lang=='en' else 'en/index.html'}">{e('route')}</a><button id="locale" type="button">{e('language')}</button></header><main><p class="eyebrow">GLOSSQUOTE LABS · EXACT GEOMETRY</p>{text('title','h1')}{text('subtitle','p','class="subtitle"')}<div class="workspace"><section class="panel">{text('setup','h2')}<form id="form" novalidate>{controls}{text('dimensionHint','p','id="dimensionHint" class="hint"')}<label for="pattern" data-t="pattern">{e('pattern')}</label><select id="pattern">{options(['checker','diagonal'])}</select>{text('coordinateHint','p','id="coordinateHint" class="hint"')}<fieldset><legend data-t="rows">{e('rows')}</legend><div id="rows"></div></fieldset><div class="actions">{text('add','button','id="add" type="button"')}{text('remove','button','id="remove" type="button"')}</div>{text('limit','p','id="limit" class="hint"')}<label for="preset" data-t="preset">{e('preset')}</label><select id="preset">{options(['rectangle','triangle','concave','twelve'])}</select>{text('apply','button','id="apply" type="button"')}<p id="error" class="error" hidden></p><div class="actions">{text('generate','button','id="generate" type="submit" class="primary"')}{text('reset','button','id="reset" type="button"')}</div></form></section><section class="panel results"><p id="status" role="status" aria-live="polite"></p><div id="generated" hidden>{text('schematic','h2')}<div id="diagram" aria-hidden="true"></div><p id="summary"></p>{text('native','h2')}<div class="preview-scroll" tabindex="0" aria-label="{e('native')}"><div id="box"><div id="face" class="checker" aria-hidden="true"></div></div></div><p id="layout"></p></div></section></div><section class="panel">{text('table','h2')}<div class="table-scroll" tabindex="0" aria-label="{e('table')}"><table><caption>P0–P11</caption><thead><tr><th>ID</th><th>x %</th><th>y %</th><th>x px</th><th>y px</th></tr></thead><tbody id="resultRows"></tbody></table></div><p id="bounds"></p>{text('css','h2')}<label for="css" data-t="cssLabel">{e('cssLabel')}</label><textarea id="css" readonly rows="4"></textarea>{text('select','button','id="select" type="button" disabled')}</section><section class="panel">{text('helpTitle','h2')}{text('help','p')}{text('help2','p')}{text('privacy','p')}</section></main><footer>GlossQuote Labs · private preview · noindex</footer><noscript>{'需要 JavaScript；不提供假成功預覽。' if lang=='zh' else 'JavaScript is required; no successful preview without it.'}</noscript></body></html>'''
 (r/('public/index.html' if lang=='zh' else 'public/en/index.html')).write_text(body+'\n')
(r/'src/app.mjs').write_text('import {initialState,reduce,exact,approx,canonical} from "./core.mjs";\nconst texts='+json.dumps(t,ensure_ascii=False)+';\n'+(r/'src/app-template.mjs').read_text())
